import json,pathlib,re
root=pathlib.Path(__file__).resolve().parents[1];path=root/'dist/data/relation-atlas.json';a=json.loads(path.read_text());base=json.loads((root/'dist/data/history.json').read_text());dictionary_path=root/'dist/locales/en.json';en=json.loads(dictionary_path.read_text());texts={}
a['cultures']=[];a['relations']=[r for r in a['relations'] if not r['id'].startswith('deep-')];a['nodes']=[n for n in a['nodes'] if not n['id'].startswith('deep-')]
def T(pair):
 ru,english=pair.split('||',1);assert not re.search('[А-Яа-яЁё]',english),english;texts[ru]=english;return ru
def S(id,pair,url):a['sources'][id]={'title':T(pair),'url':url}
