# Compact bilingual profiles are authored field by field. No generated neighbouring-region filler.
def C(id,name,start,end,x,y,region,kind,summary,government,society,economy,belief,src,area_names=()):
 a['nodes']=[n for n in a['nodes'] if n['id']!=id] # explicitly promote an existing network waypoint when applicable
 c=dict(id=id,name=T(name),start=start,end=end,coordinates=[x,y],region=region,kind=T(kind),summary=T(summary),government=T(government),society=T(society),economy=T(economy),beliefSummary=T(belief),religions=['ritual'],sources=src.split(','),rulers=[],events=[],aliases=' '.join(area_names),areaNames=list(area_names),approximate=True,note=T('Даты обозначают обзорный период этой истории. Археологическая культура не равнозначна единому народу или государству; границы и политические формы менялись.||Dates define the overview period of this account. An archaeological culture is not equivalent to a single people or state; boundaries and political forms changed.'))
 a['cultures'].append(c);return c
C('deep-mehrgarh','Мехргарх||Mehrgarh',-7000,-2600,67.62,29.39,'Азия','Поселения земледельцев||Farming settlements','У подножия Боланского прохода земледелие и скотоводство сочетались с изготовлением украшений из привозного сырья.||At the foot of the Bolan Pass, farming and herding accompanied the production of ornaments from imported materials.','Домохозяйства и местные сообщества; царская династия не установлена.||Households and local communities; no royal dynasty has been established.','Сырцовые дома, хранение зерна, погребения и специализированные мастерские.||Mud-brick houses, grain storage, burials and specialized workshops.','Пшеница, ячмень, разведение животных, обработка раковин и каменных бус.||Wheat, barley, livestock, shell working and stone beads.','Украшения сопровождали умерших; названия божеств и содержание верований не восстановлены.||Ornaments accompanied the dead; names of deities and the content of beliefs are not recovered.','deep-mehrgarh,deep-lapis',('Mehrgarh',))
C('deep-halaf','Халафские общества||Halaf societies',-6500,-5500,40.04,36.83,'Азия','Археологическая культура||Archaeological culture','Земледельческие поселения Северной Месопотамии и Сирии объединяет расписная керамика, а не известная общая царская власть.||Farming settlements of northern Mesopotamia and Syria share painted pottery, rather than a known common kingship.','Местные поселковые сообщества; единого государства не выявлено.||Local village communities; no unified state has been identified.','Земледельцы, скотоводы и гончары жили в поселениях с круглыми и прямоугольными постройками.||Farmers, herders and potters occupied settlements with round and rectangular buildings.','Выращивание зерна, животноводство и тонкая расписная керамика.||Cereal cultivation, livestock and fine painted pottery.','Фигурки и погребальные обряды отражают ритуальную жизнь, но не позволяют назвать единую религию.||Figurines and burial practices reflect ritual life without establishing a single named religion.','deep-halaf',('Halaf','Halaf culture'))
C('deep-ubaid','Убейдские общества||Ubaid societies',-6500,-3800,45.99,30.82,'Азия','Археологическая культура||Archaeological culture','На юге Месопотамии росли поселения с общественными сооружениями. Убейдская керамика достигала берегов Персидского залива.||Settlements with communal buildings developed in southern Mesopotamia. Ubaid pottery reached the shores of the Persian Gulf.','Поселковые элиты и общественные центры; формы власти различались.||Village elites and communal centres; forms of authority varied.','Домохозяйства занимались земледелием, рыболовством и ремеслом; возрастала специализация труда.||Households farmed, fished and practiced crafts, with increasing specialization.','Орошаемое земледелие, рыбные ресурсы и преимущественно местный обмен.||Irrigated farming, fisheries and predominantly local exchange.','Общественные здания и изображения связаны с обрядами; преемственность отдельных культов остаётся предметом исследований.||Communal buildings and images relate to ritual; continuity of particular cults remains under study.','deep-ubaid',('Ubaid','Ubaid culture'))
C('deep-longshan','Луншаньские общества||Longshan societies',-3000,-1900,117.53,36.72,'Азия','Археологические общества||Archaeological societies','Укреплённые поселения бассейна Хуанхэ отличались ремесленной специализацией и заметным имущественным расслоением.||Fortified settlements of the Yellow River basin show craft specialization and pronounced differences in wealth.','Несколько центров местной власти; общая империя не установлена.||Multiple centres of local authority; no common empire has been established.','Поселения с оборонительными стенами, элитными погребениями и производством тонкой чёрной керамики.||Walled settlements, elite burials and production of fine black pottery.','Земледелие, скотоводство, гончарство и обработка ритуальных материалов.||Farming, herding, pottery and working of ritual materials.','Погребальные различия и ритуальные предметы свидетельствуют о почитании умерших и статусных обрядах.||Differences in burials and ritual objects attest to practices involving the dead and social status.','deep-china,deep-erlitou',('Longshan','Longshan culture'))
C('deep-erlitou','Эрлитоу||Erlitou',-1850,-1600,112.7,34.68,'Азия','Ранний бронзовый центр||Early Bronze Age centre','В долине Хуанхэ сложился крупный центр с дворцовыми комплексами, дорогами и специализированным бронзолитейным производством.||A major centre in the Yellow River valley developed palatial compounds, roads and specialized bronze casting.','Ранняя централизованная власть; отождествление с династией Ся остаётся спорным.||Early centralized authority; identification with the Xia dynasty remains disputed.','Элитные кварталы и мастерские отражают управление трудом и доступом к престижным вещам.||Elite quarters and workshops reflect control of labour and access to prestige objects.','Бронзовые сосуды, бирюзовые инкрустации, земледельческое снабжение.||Bronze vessels, turquoise inlay and agricultural provisioning.','Сосуды и погребальные комплексы указывают на элитные ритуалы; тексты с именами правителей отсутствуют.||Vessels and burials indicate elite ritual; texts naming rulers are absent.','deep-erlitou',('Erlitou',))
C('deep-elam','Элам · Сузы и Аншан||Elam · Susa and Anshan',-2700,-1500,48.26,32.19,'Азия','Царства и региональные центры||Kingdoms and regional centres','Низменные Сузы и нагорные центры Ирана входили в меняющиеся политические объединения. Их история связана с соседями Месопотамии, но не сводится к ним.||Lowland Susa and highland centres of Iran belonged to changing political formations, with histories connected to but distinct from Mesopotamia.','Региональные династии и союзы; власть над Сузами и Аншаном не всегда была единой.||Regional dynasties and alliances; Susa and Anshan did not always share one authority.','Писцы, храмовые хозяйства, ремесленники и земледельческие общины.||Scribes, temple households, craftspeople and farming communities.','Земледелие, обработка металла и камня, сухопутные и морские контакты.||Farming, metal and stone working, and overland and maritime contacts.','Местные божества и храмовые традиции сосуществовали с заимствованными образами.||Local deities and temple traditions coexisted with adopted imagery.','deep-iran,deep-gulf',('Elam','Elamite Kingdoms','Old Elamite Kingdom'))
C('deep-akkad','Аккадская держава||Akkadian Empire',-2334,-2154,44.5,33.1,'Азия','Раннее территориальное государство||Early territorial state','Саргон и его преемники подчинили ряд месопотамских городов. Двор, войско и назначенные управители связывали земли с разными языками и культами.||Sargon and his successors subdued Mesopotamian cities. Court, army and appointed governors linked lands with different languages and cults.','Монархия с царскими назначенцами и зависимыми городскими правителями.||Monarchy with royal appointees and subordinate urban rulers.','Храмы и домохозяйства продолжали существовать внутри более широкой системы власти.||Temples and households continued within a wider political system.','Земледельческие доходы, военная добыча, ремесло и обмен по речным и заливным путям.||Agricultural revenues, booty, crafts and exchange along river and Gulf routes.','Городские божества сохраняли значение; царская идеология использовала культ Иштар и других богов.||City deities remained important; royal ideology drew on Ishtar and other gods.','deep-cities,deep-sargon',('Akkadian Empire','Akkad'))
C('deep-uriii','Ур · III династия||Ur · Third Dynasty',-2112,-2004,46.1,30.96,'Азия','Бюрократическая монархия||Bureaucratic monarchy','Царская власть Ура управляла значительными областями Южной Месопотамии через чиновников, учёт труда и поставок.||Royal government at Ur administered much of southern Mesopotamia through officials and records of labour and supplies.','Монархия с провинциальными управителями и развитой письменной администрацией.||Monarchy with provincial governors and extensive written administration.','Хозяйства храмов и дворца учитывали зерно, стада и рабочие коллективы.||Temple and palace households recorded grain, herds and work teams.','Орошение, шерстяные ткани, животноводство и поступление привозного сырья.||Irrigation, wool textiles, livestock and imported raw materials.','Царское строительство храмов и культы городских богов связывали власть с сакральными центрами.||Royal temple construction and city cults linked government to sacred centres.','deep-babylon,deep-gulf',('Third Dynasty of Ur','Ur III'))
C('deep-mari','Мари · города на Евфрате||Mari · cities on the Euphrates',-2900,-1759,40.89,34.55,'Азия','Городские царства||Urban kingdoms','На одном месте последовательно существовали три города. Мари контролировал движение по Евфрату, а его дворцовые архивы раскрывают мир переговоров и соперничества.||Three successive cities occupied the same site. Mari controlled movement along the Euphrates, while palace archives reveal diplomacy and rivalry.','Сменявшиеся царские династии; разрушения и перестройки разделяют периоды истории.||Successive royal dynasties; destruction and rebuilding divide its historical phases.','Двор, храмовые учреждения, ремесленные кварталы и связи с кочевыми сообществами.||Court, temple institutions, craft districts and ties with mobile communities.','Речной транзит, обработка меди и бронзы, зерновое хозяйство.||River transit, copper and bronze working, and cereal farming.','Храмы и городские божества играли важную роль в ритуале и легитимации власти.||Temples and city deities played important roles in ritual and political legitimacy.','deep-mari,deep-mari-tech',('Mari','Kingdom of Mari'))
C('deep-babylon','Вавилон · первая династия||Babylon · First Dynasty',-1894,-1595,44.42,32.54,'Азия','Аморейская монархия||Amorite monarchy','При Хаммурапи небольшой центр превратился в одну из ведущих держав Месопотамии. Законы, письма и хозяйственные документы показывают сложное общество.||Under Hammurabi a modest centre became a leading Mesopotamian power. Laws, letters and economic records reveal a complex society.','Царь, городские учреждения, судьи и администрация.||King, urban institutions, judges and administration.','Свободные домохозяйства, зависимые работники и порабощённые люди имели неодинаковые права.||Free households, dependent workers and enslaved people had unequal rights.','Поля и каналы, аренда, ремесло, серебряные расчёты и торговые посредники.||Fields and canals, tenancy, crafts, silver payments and commercial intermediaries.','Мардук и другие городские боги входили в политическую и храмовую жизнь.||Marduk and other city gods were part of political and temple life.','deep-babylon',('First Babylonian Dynasty','Old Babylonian Empire','Babylonia'))
C('ashur-trade','Ашшур · староассирийские общества||Ashur · Old Assyrian societies',-2100,-1700,43.26,35.46,'Азия','Город и купеческие сети||City and merchant networks','Купеческие семьи Ашшура вели дела с анатолийскими городами. Письма показывают участие женщин в производстве тканей и управлении семейным хозяйством.||Merchant families of Ashur traded with Anatolian towns. Letters show women producing textiles and managing household affairs.','Правитель города, городской совет и купеческие учреждения.||City ruler, civic assembly and merchant institutions.','Семейные предприятия, долговые договоры, посредники и общины купцов за пределами города.||Family firms, credit contracts, intermediaries and merchant communities abroad.','Олово и ткани отправлялись в Анатолию, серебро возвращалось в расчётах.||Tin and textiles went to Anatolia, with silver used for return payments.','Культ Ашшура и других божеств сопровождал клятвы, договоры и повседневные обряды.||Ashur and other deities featured in oaths, contracts and daily rites.','deep-assur',('Old Assyrian Empire','Old Assyrian Kingdom'))
C('deep-hittites','Хеттское царство||Hittite kingdom',-1650,-1180,34.62,40.02,'Азия','Дворцовая монархия||Palatial monarchy','Из Хаттусы правители управляли анатолийскими областями и заключали договоры с соседями и зависимыми царями.||From Hattusha, rulers governed Anatolian lands and negotiated treaties with neighbours and dependent kings.','Царская династия, дворцовые чиновники и зависимые правители.||Royal dynasty, palace officials and subordinate rulers.','Разноязычное население, земледельцы, мастера и храмовые служители.||Multilingual populations, farmers, craftspeople and temple personnel.','Земледельческие поставки, скотоводство, металлургия и международный обмен.||Agricultural supplies, herding, metallurgy and international exchange.','Множество местных и заимствованных богов, праздники и государственные ритуалы.||Numerous local and adopted gods, festivals and state rituals.','deep-hattusha',('Hittite Empire','Hittite Kingdom'))
C('deep-kerma','Керма · раннее царство Куш||Kerma · early kingdom of Kush',-2450,-1450,30.41,19.6,'Африка','Нубийское царство||Nubian kingdom','Керма выросла в самостоятельный центр власти Верхней Нубии. Монументальные сырцовые здания, тонкая керамика и царские курганы отражают её богатство.||Kerma became an independent centre of power in Upper Nubia. Monumental mud-brick buildings, fine pottery and royal tumuli reflect its wealth.','Местная царская власть; особенно сильная в классический период Кермы.||Local kingship, especially powerful during the Classic Kerma period.','Скотоводческие и земледельческие общины, мастера и военная элита.||Herding and farming communities, craftspeople and military elites.','Стада, земледелие и обмен золотом, слоновой костью и другими товарами.||Herds, farming and exchange involving gold, ivory and other goods.','Погребальные сооружения и жертвенные практики связаны с местными культами; это не просто египетская провинция.||Burial monuments and sacrificial practices relate to local cults; this was not simply an Egyptian province.','deep-kerma,deep-kerma-egypt',('Kerma','Kingdom of Kerma'))
C('deep-egypt-middle','Египет · Среднее царство||Egypt · Middle Kingdom',-2055,-1650,32.65,25.72,'Африка','Царская монархия||Royal monarchy','После периода раздробленности египетские правители вновь укрепили центральную власть. Южные крепости контролировали передвижение по Нилу.||After political fragmentation, Egyptian rulers rebuilt central authority. Southern fortresses controlled movement along the Nile.','Фараон, центральные чиновники и провинциальная администрация.||Pharaoh, central officials and provincial administration.','Земледельческие домохозяйства, зависимые работники, писцы и ремесленники.||Farming households, dependent workers, scribes and craftspeople.','Нильское земледелие, государственные экспедиции, обмен и контроль путей в Нубию.||Nile agriculture, state expeditions, exchange and control of routes into Nubia.','Храмовые культы, царские погребения и почитание Осириса.||Temple cults, royal burials and worship of Osiris.','deep-kerma-egypt,deep-kerma',('Middle Kingdom of Egypt',))
C('egypt-new','Египет · Новое царство||Egypt · New Kingdom',-1550,-1070,32.65,25.72,'Африка','Имперская монархия||Imperial monarchy','Египетский двор участвовал в дипломатии великих держав и контролировал земли за пределами долины Нила.||The Egyptian court participated in great-power diplomacy and controlled lands beyond the Nile valley.','Фараон, военная и гражданская администрация, крупные храмы.||Pharaoh, military and civil administration, and major temples.','Земледельцы, мастера, писцы, солдаты и принудительно перемещённые люди.||Farmers, craftspeople, scribes, soldiers and forcibly displaced people.','Нильское земледелие, дань, дворцовые дары и дальние поставки сырья.||Nile agriculture, tribute, court gifts and distant supplies of raw materials.','Культы Амона, Ра и других богов; амарнский эпизод не был общей религией всего периода.||Cults of Amun, Ra and other gods; the Amarna episode was not the religion of the entire period.','ra-amarna,deep-hattusha',('New Kingdom of Egypt',))
C('deep-kush','Куш · Напата и Мероэ||Kush · Napata and Meroe',-800,350,33.72,16.94,'Африка','Нильское царство||Nile kingdom','Кушитские династии правили из нубийских центров, а некоторое время и Египтом. В Мероэ развивались собственные письмо, храмовое искусство и производство.||Kushite dynasties ruled from Nubian centres and for a time governed Egypt. Meroe developed its own writing, temple art and production.','Царские династии и храмовые центры; власть меняла свою географию.||Royal dynasties and temple centres; the geography of power shifted.','Городские мастера и земледельческие сообщества, царская и жреческая элита.||Urban craftspeople and farming communities, with royal and priestly elites.','Земледелие, животноводство, железообработка и нильские пути обмена.||Farming, livestock, iron working and Nile exchange routes.','Амун и местные божества, включая Апедемака; египетские формы получали собственное значение.||Amun and local deities including Apedemak; Egyptian forms acquired local meanings.','deep-meroe',('Kingdom of Kush','Kush','Meroe'))
C('deep-aksum','Аксумское царство||Kingdom of Aksum',100,700,38.72,14.13,'Африка','Монетная монархия||Coin-issuing monarchy','Нагорный Аксум связывал внутренние районы Африки с Красным морем через порт Адулис. Царские монеты и стелы выражали власть.||Highland Aksum linked inland Africa to the Red Sea through Adulis. Royal coins and stelae expressed authority.','Царская власть с монетной чеканкой и центрами управления.||Kingship with coinage and administrative centres.','Земледельцы нагорий, ремесленники, торговые посредники и портовые сообщества.||Highland farmers, craftspeople, trading intermediaries and port communities.','Земледелие, слоновая кость, монеты и красноморская торговля.||Agriculture, ivory, coinage and Red Sea commerce.','Местные культы предшествовали принятию христианства двором в IV веке; перемены не были мгновенными для всех.||Local cults preceded the court’s adoption of Christianity in the fourth century; change was not instantaneous for everyone.','deep-aksum',('Aksum','Aksumite Empire','Kingdom of Aksum'))
C('deep-minoan','Крит · минойские дворцовые общества||Crete · Minoan palatial societies',-2000,-1450,25.16,35.3,'Европа','Дворцовые общества||Palatial societies','Кносс, Фест и другие критские центры связывали сельские хозяйства с дворцовыми мастерскими и морскими контактами.||Knossos, Phaistos and other Cretan centres linked rural production to palace workshops and maritime contacts.','Несколько дворцовых центров; отношения между ними менялись.||Multiple palatial centres whose relationships changed.','Дворцовые служители, ремесленники, земледельцы и мореплаватели.||Palace personnel, craftspeople, farmers and seafarers.','Вино, масло, ткани и изделия мастеров; ввоз металлов и престижного сырья.||Wine, oil, textiles and craft goods; imports of metals and prestige materials.','Святилища, подношения и изображения отражают обряды; письменность линейного письма А не расшифрована.||Sanctuaries, offerings and images reflect ritual; Linear A remains undeciphered.','deep-minoan',('Minoan Civilization','Minoans','Minoan Crete'))
C('deep-mycenaean','Микенские дворцовые царства||Mycenaean palatial kingdoms',-1600,-1100,22.76,37.73,'Европа','Несколько дворцовых государств||Multiple palatial states','Микены, Пилос и другие центры имели собственные дворцы. Таблички линейного письма Б фиксируют раннюю форму греческого языка.||Mycenae, Pylos and other centres had separate palaces. Linear B tablets record an early form of Greek.','Дворцовые правители и администрация; единого греческого государства не было.||Palatial rulers and administration; there was no unified Greek state.','Земледельческие общины, зависимые работники, мастера и военная знать.||Farming communities, dependent workers, craftspeople and military elites.','Учёт земли и стад, текстиль, бронза, масло и дальние морские контакты.||Records of land and herds, textiles, bronze, oil and long-distance sea contacts.','Боги, часть имён которых известна позднейшим грекам, получали дворцовые подношения.||Gods, some with names familiar to later Greeks, received palatial offerings.','deep-mycenaean',('Mycenaean Greece','Mycenaeans','Mycenaean Civilization'))
C('deep-phoenicia','Финикийские города||Phoenician cities',-1200,-332,35.2,33.27,'Азия','Городские царства и морские общины||City kingdoms and maritime communities','Тир, Сидон, Библ и другие города имели собственные власти и морские сети. «Финикийцы» не означают единое государство.||Tyre, Sidon, Byblos and other cities had separate governments and maritime networks. “Phoenicians” does not mean a single state.','Городские цари и влиятельные торговые семьи; периоды внешней зависимости.||City kings and influential trading families, with periods of external dependence.','Мореплаватели, ремесленники, сельские общины и переселенцы в заморских поселениях.||Seafarers, craftspeople, rural communities and settlers in overseas settlements.','Дерево, ткани, красители, стекло, металл и торговое посредничество.||Timber, textiles, dyes, glass, metal and commercial intermediation.','Городские божества и святилища различались; культы переносились и переосмысливались в новых поселениях.||City gods and sanctuaries varied; cults were carried to and reinterpreted in new settlements.','ra-phoenicia',('Phoenicia','Phoenician City-States'))
C('deep-olmec','Ольмекские центры||Olmec centres',-1200,-400,-94.76,17.74,'Америка','Ранние сложные общества||Early complex societies','Сан-Лоренсо и Ла-Вента известны монументальной скульптурой и дальним перемещением камня. Общий стиль не доказывает единой империи.||San Lorenzo and La Venta are known for monumental sculpture and long-distance movement of stone. A shared style does not establish a single empire.','Местные центры власти и ритуальные элиты.||Local centres of authority and ritual elites.','Земледельцы, мастера и организаторы крупных общественных работ.||Farmers, craftspeople and organizers of large communal works.','Маисовое земледелие, обработка базальта и зелёного камня.||Maize farming and working of basalt and greenstone.','Образы людей и животных, подношения и ритуальные предметы связаны с властью и плодородием.||Human-animal imagery, offerings and ritual objects related to power and fertility.','deep-olmec',('Olmec','Olmec Civilization'))
C('deep-chavin','Чавин · андские ритуальные центры||Chavín · Andean ritual centres',-900,-200,-77.18,-9.59,'Америка','Ритуальные и обменные сети||Ritual and exchange networks','Храмовый центр Чавин-де-Уантар участвовал в широком распространении художественных образов и ритуальных вещей в Андах.||The temple centre of Chavín de Huántar participated in the widespread circulation of imagery and ritual objects across the Andes.','Ритуальные авторитеты и местные элиты; не доказана единая имперская администрация.||Ritual authorities and local elites; a single imperial administration is not established.','Высокогорные и прибрежные сообщества сохраняли разные занятия и местные традиции.||Highland and coastal communities retained different livelihoods and local traditions.','Земледелие, скотоводство, ремесло и перемещение редких материалов.||Farming, herding, crafts and movement of rare materials.','Ритуалы использовали образы хищников и преобразования человеческого тела; имена многих божеств неизвестны.||Ritual employed predator imagery and transformations of the human body; names of many deities are unknown.','deep-chavin',('Chavin','Chavín'))
C('deep-moche','Моче · северное побережье Анд||Moche · northern Andean coast',100,800,-79.01,-8.13,'Америка','Региональные общества||Regional societies','В долинах северного побережья Перу развивались центры с храмовыми платформами, сложной керамикой и искусной обработкой металла.||Valleys of Peru’s northern coast developed centres with temple platforms, elaborate pottery and skilled metalworking.','Несколько региональных элит; политическая организация менялась по долинам и времени.||Multiple regional elites; political organization varied between valleys and periods.','Земледельцы орошаемых долин, рыбаки, мастера и ритуально-военная элита.||Farmers in irrigated valleys, fishers, craftspeople and ritual-military elites.','Орошение, морские ресурсы, керамика, ткани и металлические изделия.||Irrigation, marine resources, pottery, textiles and metal objects.','Изображения и погребения раскрывают обряды власти, жертвоприношения и взаимодействие со сверхъестественными существами.||Images and burials reveal rituals of authority, sacrifice and interaction with supernatural beings.','deep-andes',('Moche','Moche Civilization'))
C('deep-teotihuacan','Теотиуакан||Teotihuacan',100,650,-98.84,19.69,'Америка','Крупный городской центр||Major urban centre','Один из крупнейших городов древней Америки объединял многообразные кварталы, пирамиды, мастерские и дальние сети обмена.||One of the largest cities of the ancient Americas brought together diverse neighbourhoods, pyramids, workshops and distant exchange networks.','Мощные городские институты; устройство верховной власти остаётся спорным.||Powerful urban institutions; the structure of supreme authority remains debated.','Многосемейные жилые комплексы, ремесленные кварталы и жители разного происхождения.||Multi-family residential compounds, craft districts and people of varied origins.','Обсидиановые мастерские, керамика, сельское снабжение и привозные товары.||Obsidian workshops, pottery, agricultural provisioning and imported goods.','Монументальные святилища, посвящения и обряды с подношениями и жертвоприношениями.||Monumental sanctuaries, dedications and rites involving offerings and sacrifice.','deep-teotihuacan,deep-teot-obsidian',('Teotihuacan','Teotihuacán'))
C('deep-tikal','Тикаль · царство майя||Tikal · Maya kingdom',250,900,-89.62,17.22,'Америка','Городское династическое царство||Urban dynastic kingdom','Тикаль был одним из крупных центров классического мира майя. Храмы, дворцы и надписи показывают длительную историю местной династии.||Tikal was a major centre of the Classic Maya world. Temples, palaces and inscriptions reveal a long local dynastic history.','Царская династия и двор; другие города майя имели собственных правителей.||Royal dynasty and court; other Maya cities had their own rulers.','Земледельческие общины, придворные, писцы и мастера.||Farming communities, courtiers, scribes and craftspeople.','Маисовое земледелие, ремесло и обмен между городами и природными зонами.||Maize farming, crafts and exchange between cities and ecological zones.','Династические ритуалы, календарные циклы, почитание предков и многочисленных божеств.||Dynastic rituals, calendar cycles, ancestors and numerous deities.','deep-tikal',('Tikal',))
C('deep-tiwanaku','Тиуанако||Tiwanaku',400,1000,-68.67,-16.55,'Америка','Высокогорный политико-ритуальный центр||Highland political and ritual centre','У южного берега Титикаки возник мощный центр с монументальными каменными сооружениями и влиянием на удалённые андские области.||Near the southern shore of Titicaca, a powerful centre developed monumental stone architecture and influence in distant Andean regions.','Центральная элита и региональные формы зависимости; механизмы управления обсуждаются.||A central elite and regional forms of dependence; governing mechanisms remain debated.','Земледельцы высокогорья, пастухи, мастера и жители ритуального центра.||Highland farmers, herders, craftspeople and residents of the ritual centre.','Земледелие в высокогорных условиях, стада лам и межрегиональные контакты.||High-altitude agriculture, llama herds and interregional contacts.','Монументальные комплексы и изображения выражали общие ритуальные представления, адаптировавшиеся в разных местах.||Monumental complexes and imagery expressed shared ritual ideas adapted in different places.','deep-tiwanaku',('Tiwanaku','Tiahuanaco'))
C('deep-lapita','Лапита · островные мореплаватели||Lapita · island seafarers',-1500,-500,151.5,-4.3,'Океания','Археологические морские сообщества||Archaeological maritime communities','От архипелага Бисмарка к удалённым островам распространялись сообщества с характерной керамикой. Заселение Фиджи и Тонга происходило позднее начала этой традиции.||Communities with distinctive pottery spread from the Bismarck Archipelago to remote islands. Settlement of Fiji and Tonga occurred later than the start of the tradition.','Местные общины и родственные сети; единого островного государства не было.||Local communities and kin networks; there was no single island state.','Мореходство, прибрежные поселения, выращивание растений и использование морских ресурсов.||Seafaring, coastal settlements, horticulture and use of marine resources.','Керамика, раковины, каменные орудия и дальнее перемещение обсидиана.||Pottery, shell, stone tools and long-distance movement of obsidian.','Погребения и декор керамики отражают социальные и ритуальные связи; поздние религии нельзя переносить на весь период.||Burials and pottery decoration reflect social and ritual ties; later religions cannot be projected across the entire period.','ra-lapita,ra-lapita-obsidian',('Lapita','Lapita Culture'))
C('deep-nabataea','Набатейское царство||Nabataean kingdom',-300,106,35.44,30.33,'Азия','Караванная монархия||Caravan monarchy','Петра и Хегра связывали пустынные пути с рынками Восточного Средиземноморья. Водосборные сооружения поддерживали жизнь городов в сухой среде.||Petra and Hegra connected desert routes to eastern Mediterranean markets. Water-harvesting systems sustained urban life in an arid environment.','Царская династия, местные элиты и городские учреждения.||Royal dynasty, local elites and urban institutions.','Караванные посредники, камнерезы, земледельцы и жители пустынных поселений.||Caravan intermediaries, stonecutters, farmers and desert settlement residents.','Благовония, транзитные товары, земледелие и управление водными ресурсами.||Incense, transit goods, agriculture and water management.','Местные боги, священные камни и изображения разных художественных традиций.||Local gods, sacred stones and images drawing on varied artistic traditions.','deep-nabataea,deep-petra',('Nabataean Kingdom','Nabataea','Nabataeans'))
C('deep-gandhara','Гандхара · города и монастыри||Gandhara · towns and monasteries',100,500,71.6,34.1,'Азия','Регион культурных контактов||Region of cultural contacts','Северо-запад Южной Азии связывал морские рынки с горными проходами и путями Центральной Азии. Многоязычные элиты поддерживали буддийские центры.||Northwestern South Asia connected maritime markets with mountain passes and Central Asian routes. Multilingual elites supported Buddhist centres.','Область разных царств и местных властей, а не неизменное единое государство.||A region of changing kingdoms and local authorities, not an unchanging unified state.','Городские жители, купцы, земледельцы и монастырские общины.||Townspeople, merchants, farmers and monastic communities.','Межрегиональная торговля, ремесло и пожертвования монастырям.||Interregional commerce, crafts and donations to monasteries.','Буддийские культы развивались рядом с другими традициями; искусство соединяло местные и заимствованные формы.||Buddhist cults developed alongside other traditions; art combined local and adopted forms.','deep-gandhara',('Gandhara',))
# Dates of named rulers follow the cited museum chronologies, not undated profiles.
by_id={c['id']:c for c in base['cultures']+a['nodes']+a['cultures']}
by_id['deep-akkad']['rulers']=[dict(name=T('Саргон Аккадский||Sargon of Akkad'),start=-2334,end=-2279)]
by_id['deep-babylon']['rulers']=[dict(name=T('Хаммурапи||Hammurabi'),start=-1792,end=-1750)]
by_id['deep-akkad']['events']=[dict(year=-2334,text=T('Около этого времени начинается правление Саргона; даты следуют средней хронологии.||Sargon’s reign begins around this time; dates follow the middle chronology.'))]
by_id['deep-mari']['events']=[dict(year=-2550,text=T('Около этого времени начинается новый этап перестройки города.||A new phase of urban rebuilding begins around this time.')),dict(year=-1759,text=T('Разрушение Мари войсками Хаммурапи завершает историю царского центра этого периода.||Destruction by Hammurabi’s forces ends this phase of Mari as a royal centre.'))]
