# Relationship fields retain substantive differences between transport, gifts,
# political control, craft transmission and religious exchange.
def R(slug,f,t,start,end,goods,returns,impact,source,kind='trade',evidence=None,note=None,directness='network'):
 assert f in by_id and t in by_id,(slug,f,t)
 for id in [f,t]:assert by_id[id]['start']<=start<=end<=by_id[id]['end'],(slug,id,start,end,by_id[id]['start'],by_id[id]['end'])
 title=by_id[f]['name']+' ↔ '+by_id[t]['name'];english=lambda x:texts.get(x,en.get(x,x));texts[title]=english(by_id[f]['name'])+' ↔ '+english(by_id[t]['name'])
 a['relations'].append(dict(id='deep-'+slug,**{'from':f,'to':t},start=start,end=end,type=kind,title=title,goods=T(goods),returns=T(returns),impact=T(impact),sources=source.split(','),evidence=T(evidence or 'Археологические находки и исторические исследования||Archaeological finds and historical research'),directness=directness,approximate=True,periodNote=T(note or 'Округлённый обзорный интервал свидетельств. Линия не задаёт единственный маршрут и не доказывает непрерывный контакт в каждом году.||A rounded overview interval of evidence. The line does not define a single route or prove uninterrupted contact in every year.')))
